-- C11/P11.7 additive provider connection/capability evidence. Repository-only; no live connection authorized.
create table if not exists public.command_center_book_publishing_provider_connections(
 owner_id uuid not null references auth.users(id) on delete cascade, provider_key text not null check(btrim(provider_key)<>''), version integer not null check(version>0), health text not null check(health in('available','degraded','unavailable')), connection_state text not null check(connection_state in('disconnected','connected','owner_action_required','unavailable')), credential_ref text, formats text[] not null check(cardinality(formats)>0), capabilities jsonb not null, execution_boundary text not null check(execution_boundary in('normal_chat','work_required','owner_only')), owner_action_required boolean not null, evidence_refs text[] not null check(cardinality(evidence_refs)>0), receipt_refs text[] not null default '{}', error_refs text[] not null default '{}', replaces_provider_key text, migration_ref text, observed_at timestamptz not null, primary key(owner_id,provider_key,version), check(credential_ref is null or btrim(credential_ref)<>''), check(migration_ref is null or btrim(migration_ref)<>'')
);
create or replace function public.command_center_reject_book_provider_connection_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Provider connection evidence is immutable'; end $$;
create trigger command_center_book_provider_connection_immutable before update or delete on public.command_center_book_publishing_provider_connections for each row execute function public.command_center_reject_book_provider_connection_mutation();
alter table public.command_center_book_publishing_provider_connections enable row level security; revoke all on table public.command_center_book_publishing_provider_connections from public,anon,authenticated; grant select,insert on table public.command_center_book_publishing_provider_connections to authenticated;
create policy p11_7_book_provider_connection_owner on public.command_center_book_publishing_provider_connections for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
